if($hcEnabled&&!$hcRequired)$loginNotice=aih_t('login_captcha_config',$lang);
if(!$loginConfigured){$loginNotice=aih_t('ui_login_setup_notice',$lang);}
function aih_login_captcha_ok(string $secret,string $token): bool {
    if($secret===''||$token==='')return false;
    $r=aih_http('POST','https://api.hcaptcha.com/siteverify',http_build_query(['secret'=>$secret,'response'=>$token,'remoteip'=>$_SERVER['REMOTE_ADDR']??'']),['Content-Type: application/x-www-form-urlencoded','Accept: application/json'],20);
    if($r['code']<200||$r['code']>=300)return false;$j=json_decode($r['body'],true);return !empty($j['success']);
}
if(!aih_is_logged_in() && $_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='login'){
    aih_check_csrf($_POST['csrf']??null);
    if(!$loginConfigured){http_response_code(403);$loginError=aih_t('ui_login_setup_notice',$lang);}
    elseif(!aih_auth_attempt_reserve()){
        http_response_code(429);header('Retry-After: 900');$loginError=aih_t('login_too_many',$lang);
    }
    elseif($hcRequired&&!aih_login_captcha_ok($hcSecret,(string)($_POST['h-captcha-response']??''))){
        $loginError=aih_t('login_captcha_failed',$lang);aih_audit('login_captcha_failed');
    }
    elseif(aih_auth_verify((string)($_POST['password']??''),$settings)){
        aih_auth_mark_logged_in((string)$settings['password_hash']);
        aih_auth_attempt_clear();
        if(!empty($_POST['remember']))aih_remember_issue((string)$settings['password_hash'],30);else aih_remember_forget();
        aih_audit('login_ok',['remember'=>!empty($_POST['remember'])]);
        header('Location: ./?page=chat&lang='.rawurlencode($lang));exit;
    }
    else{$loginError=aih_t('login_incorrect',$lang);usleep(500000);aih_audit('login_failed');}
}

function aih_language_select(string $lang): string { $out='';$flags=aih_language_flags();foreach(aih_languages() as$code=>$name){$label=trim((string)($flags[$code]??'').' '.$name);$out.='<option value="'.aih_e($code).'" '.($code===$lang?'selected':'').'>'.aih_e($label).'</option>';}return $out; }
