url" value="<?=aih_e((string)($settings['providers']['ollama_local_url']??''))?>"></div><div><label>LM Studio URL</label><input name="lmstudio_local_url" value="<?=aih_e((string)($settings['providers']['lmstudio_local_url']??''))?>"></div><div><label>llama.cpp URL</label><input name="llamacpp_local_url" value="<?=aih_e((string)($settings['providers']['llamacpp_local_url']??''))?>"></div><div><label>LocalAI URL</label><input name="localai_local_url" value="<?=aih_e((string)($settings['providers']['localai_local_url']??''))?>"></div><div><label>Cloudflare Account ID</label><input name="cloudflare_account_id" value="<?=aih_e((string)($settings['providers']['cloudflare_account_id']??''))?>" placeholder="Cloudflare account ID"><small>Needed only when Cloudflare Workers AI is enabled. Create a Workers AI API token in Cloudflare and paste it in the provider key field above.</small></div><div><label>Custom OpenAI-compatible URL</label><input name="custom_openai_url" value="<?=aih_e((string)($settings['providers']['custom_openai_url']??''))?>"></div></div><h2><?=aih_e(aih_t('search_connections',$lang))?></h2><p class="muted">Smart Search merges multiple independent sources. DuckDuckGo + Wikipedia work automatically; developer searches can also use GitHub, Stack Overflow, npm, Packagist and the WordPress.org plugin/theme directory, while research queries can add Hacker News and arXiv. Add up to three SearXNG instances or optional Brave/Ollama Web Search credentials for broader coverage.</p><div class="form-grid"><div><label>SearXNG URLs</label><input name="searxng_url" value="<?=aih_e((string)($settings['search']['searxng_url']??''))?>" placeholder="https://search.example, https://searx.example"><small>One to three SearXNG JSON-capable instances, separated by commas. A self-hosted instance is most reliable.</small></div><div><label>Ollama Web Search key</label><input type="password" name="ollama_web_key" placeholder="<?=empty($settings['search']['ollama_web_key'])?aih_e(aih_t('optional_api_key',$lang)):'Saved - leave empty to keep'?>"></div><div><label>Brave Search API key</label><input type="password" name="brave_search_key" placeholder="<?=empty($settings['search']['brave_search_key'])?aih_e(aih_t('optional_api_key',$lang)):'Saved - leave empty to keep'?>"><small>Optional. Leave blank to keep the fully free/no-key path.</small></div></div><label class="toggle"><input type="checkbox" name="smart_grounding" <?=!empty($settings['search']['smart_grounding'])?'checked':''?>><span><b>Smart live grounding</b><small>For current/research questions, AI Chat automatically searches the web first and answers from the retrieved sources.</small></span></label><label class="toggle"><input type="checkbox" name="developer_grounding" <?=!empty($settings['search']['developer_grounding'])?'checked':''?>> <span><b>Developer source grounding</b><small>For coding/web-development questions, add free public results from GitHub repositories, Stack Overflow, npm, Packagist and the WordPress.org plugin/theme directory when relevant.</small></span></label><label class="toggle"><input type="checkbox" name="research_sources" <?=!empty($settings['search']['research_sources'])?'checked':''?>> <span><b>Research source expansion</b><small>For research/current topics, add Hacker News and arXiv alongside the normal search engines.</small></span></label><label class="toggle"><input type="checkbox" name="ai_enrich" <?=!empty($settings['search']['ai_enrich'])?'checked':''?>><span>AI structures only facts present in search titles/snippets; missing facts remain blank.</span></label><h2><?=aih_e(aih_t('media',$lang))?></h2><p class="muted">Image Auto routing is independent from chat routing. It tries local/configured generators, then multi-source free web image search (Openverse, Wikimedia, NASA, The Met + optional Unsplash/Pexels/Pixabay), then AI Horde as the final community generator. v0.6.4 can also select up to four free-source results and compose them into a downloadable card, poster, social graphic, hero or moodboard. Puter is not used automatically for images; it remains available for video.</p><div class="form-grid"><div><label>Default media provider</label><select name="image_provider"><option value="auto" <?=($settings['images']['provider']??'auto')==='auto'?'selected':''?>>Auto - all free/local providers</option><option value="sdwebui" <?=($settings['images']['provider']??'')==='sdwebui'?'selected':''?>>Local Stable Diffusion / Forge</option><option value="comfyui" <?=($settings['images']['provider']??'')==='comfyui'?'selected':''?>>Local ComfyUI</option><option value="free_web" <?=($settings['images']['provider']??'')==='free_web'?'selected':''?>>Free web images - multi-source</option><option value="aihorde" <?=($settings['images']['provider']??'')==='aihorde'?'selected':''?>>AI Horde - anonymous free queue</option><option value="cloudflare_image" <?=($settings['images']['provider']??'')==='cloudflare_image'?'selected':''?>>Cloudflare · ByteDance SDXL-Lightning</option><option value="alibaba_qwen_image" <?=($settings['images']['provider']??'')==='alibaba_qwen_image'?'selected':''?>>Alibaba · Qwen Image</option><option value="huggingface_image" <?=($settings['images']['provider']??'')==='huggingface_image'?'selected':''?>>Hugging Face · Image inference</option><option value="siliconflow_image" <?=($settings['images']['provider']??'')==='siliconflow_image'?'selected':''?>>SiliconFlow · Image API</option><option value="pollinations" <?=($settings['images']['provider']??'')==='pollinations'?'selected':''?>>Pollinations</option></select></div><div><label>Image provider priority</label><input name="media_provider_order" value="<?=aih_e(implode(',',(array)($settings['images']['order']??[])))?>"><small>Recommended: sdwebui,comfyui,cloudflare_image,alibaba_qwen_image,huggingface_image,siliconflow_image,pollinations,free_web,aihorde</small></div><div><label>Puter video model</label><input name="puter_video_model" value="<?=aih_e((string)($settings['images']['puter_video_model']??'auto'))?>" placeholder="auto"></div><div><label>Local SD/Forge URL</label><input name="sdwebui_url" value="<?=aih_e((string)($settings['images']['sdwebui_url']??''))?>"><small>Unlimited by cloud quota when this points to your own reachable Forge/A1111 server with API enabled.</small></div><div><label>Local ComfyUI URL</label><input name="comfyui_url" value="<?=aih_e((string)($settings['images']['comfyui_url']??'http://127.0.0.1:8188'))?>"><small>Use your own ComfyUI server. If Free AI Hub is hosted remotely, expose ComfyUI securely through a private/reverse tunnel rather than leaving it open to the internet.</small></div><div><label>ComfyUI checkpoint</label><input name="comfyui_checkpoint" value="<?=aih_e((string)($settings['images']['comfyui_checkpoint']??''))?>" placeholder="e.g. dreamshaperXL_v21TurboDPMSDE.safetensors"><small>Exact checkpoint filename as shown in ComfyUI.</small></div><div><label>ComfyUI width</label><input type="number" min="256" max="1536" step="64" name="comfyui_width" value="<?=aih_e((string)($settings['images']['comfyui_width']??768))?>"></div><div><label>ComfyUI height</label><input type="number" min="256" max="1536" step="64" name="comfyui_height" value="<?=aih_e((string)($settings['images']['comfyui_height']??768))?>"></div><div><label>Pollinations image model</label><input name="pollinations_model" value="<?=aih_e((string)($settings['images']['pollinations_model']??'flux'))?>"></div><div><label>Cloudflare image model</label><input name="cloudflare_image_model" value="<?=aih_e((string)($settings['images']['cloudflare_image_model']??'@cf/bytedance/stable-diffusion-xl-lightning'))?>"><small>Uses the Cloudflare Account ID + token from AI providers above.</small></div><div><label>Hugging Face image model</label><input name="huggingface_image_model" value="<?=aih_e((string)($settings['images']['huggingface_image_model']??'black-forest-labs/FLUX.1-schnell'))?>"><small>Uses the Hugging Face token from AI providers above.</small></div><div><label>Alibaba Model Studio Workspace ID</label><input name="alibaba_workspace_id" value="<?=aih_e((string)($settings['images']['alibaba_workspace_id']??''))?>" placeholder="Workspace ID"></div><div><label>Alibaba region</label><select name="alibaba_region"><option value="ap-southeast-1" <?=($settings['images']['alibaba_region']??'ap-southeast-1')==='ap-southeast-1'?'selected':''?>>Singapore - free quota eligible</option><option value="cn-beijing" <?=($settings['images']['alibaba_region']??'')==='cn-beijing'?'selected':''?>>China (Beijing)</option><option value="cn-hongkong" <?=($settings['images']['alibaba_region']??'')==='cn-hongkong'?'selected':''?>>China (Hong Kong)</option><option value="us-east-1" <?=($settings['images']['alibaba_region']??'')==='us-east-1'?'selected':''?>>US (Virginia)</option><option value="eu-central-1" <?=($settings['images']['alibaba_region']??'')==='eu-central-1'?'selected':''?>>Germany (Frankfurt)</option><option value="ap-northeast-1" <?=($settings['images']['alibaba_region']??'')==='ap-northeast-1'?'selected':''?>>Japan (Tokyo)</option></select></div><div><label>Alibaba Qwen image model</label><input name="alibaba_image_model" value="<?=aih_e((string)($settings['images']['alibaba_image_model']??'qwen-image-2.0'))?>"></div><div><label>Alibaba Model Studio API key</label><input type="password" name="alibaba_api_key" placeholder="<?=empty($settings['images']['alibaba_api_key'])?'Optional free-quota key':'Saved - leave empty to keep'?>"><small>For new-user free image quota use Singapore and enable <b>Free Quota Only</b> in Alibaba Console to prevent paid overage.</small></div><div><label>SiliconFlow image model</label><input name="siliconflow_image_model" value="<?=aih_e((string)($settings['images']['siliconflow_image_model']??'black-forest-labs/FLUX.1-schnell'))?>"></div><div><label>SiliconFlow API key</label><input type="password" name="siliconflow_api_key" placeholder="<?=empty($settings['images']['siliconflow_api_key'])?'Optional starter-credit key':'Saved - leave empty to keep'?>"></div><div><label>Unsplash Access Key</label><input type="password" name="unsplash_access_key" placeholder="<?=empty($settings['images']['unsplash_access_key'])?'Optional':'Saved - leave empty to keep'?>"><small>Add an Unsplash developer key for high-quality photographic results. Attribution/source links remain visible.</small></div><div><label>Pexels API key</label><input type="password" name="pexels_api_key" placeholder="<?=empty($settings['images']['pexels_api_key'])?'Optional':'Saved - leave empty to keep'?>"><small>Optional. If no key is available, Pexels stays available as a manual source link.</small></div><div><label>Pixabay API key</label><input type="password" name="pixabay_api_key" placeholder="<?=empty($settings['images']['pixabay_api_key'])?'Optional':'Saved - leave empty to keep'?>"><small>Optional. Adds Pixabay photo search to the automatic image grid.</small></div><div><label>Image speed / quality</label><select name="image_speed_mode"><option value="fast" <?=($settings['images']['speed_mode']??'fast')==='fast'?'selected':''?>>Fast · prefer good free photos, skip long queues</option><option value="balanced" <?=($settings['images']['speed_mode']??'')==='balanced'?'selected':''?>>Balanced · short AI queue allowed</option><option value="quality" <?=($settings['images']['speed_mode']??'')==='quality'?'selected':''?>>Quality · allow long AI Horde queues</option></select><small>Fast is recommended for normal use. It avoids waits like 20+ minutes and composes a finished card from the best reusable source instead.</small></div><div><label>AI Horde max Auto queue (seconds)</label><input type="number" min="15" max="900" name="aihorde_queue_limit" value="<?=aih_e((string)($settings['images']['aihorde_queue_limit']??45))?>"><small>In Fast/Balanced Auto mode, a longer anonymous queue is cancelled and the router continues to the next source. Explicit AI Horde requests can still wait.</small></div><div><label>AI Horde model</label><input name="aihorde_model" value="<?=aih_e((string)($settings['images']['aihorde_model']??''))?>" placeholder="Auto-pick fastest active model"><small>Leave blank to query live AI Horde worker status and select an active model with the best queue estimate.</small></div><div><label>AI Horde steps</label><input type="number" min="4" max="30" name="aihorde_steps" value="<?=aih_e((string)($settings['images']['aihorde_steps']??16))?>"><small>16 is the balanced free-community default. The router also prefers photographic/SDXL-style models for normal photo prompts and avoids anime-heavy models unless requested.</small></div><div><label>Legacy sync timeout (seconds)</label><input type="number" min="45" max="300" name="aihorde_timeout" value="<?=aih_e((string)($settings['images']['aihorde_timeout']??180))?>"><small>Only for old cached clients. v0.6.4 uses an asynchronous queue and no longer cancels a valid job after this timeout.</small></div><div><label>AI Horde API key</label><input type="password" name="aihorde_api_key" placeholder="<?=empty($settings['images']['aihorde_api_key'])?'Optional - anonymous works without a key':'Saved - leave empty to keep'?>"><small>No key is required: anonymous mode uses 0000000000 at lowest priority. Add your own free AI Horde key only for better queue priority.</small></div></div><div class="resource-grid media-resource-grid"><a href="https://openverse.org/" target="_blank" rel="noreferrer"><b>Openverse · AUTO / no key</b><span>Open-license/public-domain image search used automatically.</span></a><a href="https://commons.wikimedia.org/" target="_blank" rel="noreferrer"><b>Wikimedia Commons · AUTO / no key</b><span>Automatic source for real places, people, objects and reference media.</span></a><a href="https://images.nasa.gov/" target="_blank" rel="noreferrer"><b>NASA Images · AUTO / no key</b><span>Automatic public NASA image search for space, science and Earth topics.</span></a><a href="https://www.metmuseum.org/art/collection" target="_blank" rel="noreferrer"><b>The Met Open Access · AUTO / no key</b><span>Automatic search of public-domain Open Access artwork.</span></a><a href="https://unsplash.com/" target="_blank" rel="noreferrer"><b>Unsplash · optional API key</b><span>High-quality photography. Add an Access Key above for automatic search.</span></a><a href="https://www.pexels.com/" target="_blank" rel="noreferrer"><b>Pexels · optional API key</b><span>Photography/video library; automatic search activates when a key is configured.</span></a><a href="https://pixabay.com/" target="_blank" rel="noreferrer"><b>Pixabay · optional API key</b><span>Photos, illustrations and vectors; automatic search activates with a key.</span></a><a href="https://www.freepik.com/" target="_blank" rel="noreferrer"><b>Freepik · manual</b><span>Large image/vector library; shown as a quick source without pretending it is an unlimited no-key API.</span></a><a href="https://www.shopify.com/stock-photos" target="_blank" rel="noreferrer"><b>Burst · manual</b><span>Free stock photography from Shopify.</span></a><a href="https://stocksnap.io/" target="_blank" rel="noreferrer"><b>StockSnap · manual</b><span>Free stock photography source.</span></a><a href="https://kaboompics.com/" target="_blank" rel="noreferrer"><b>Kaboompics · manual</b><span>Free lifestyle and design-oriented photography.</span></a><a href="https://gratisography.com/" target="_blank" rel="noreferrer"><b>Gratisography · manual</b><span>Distinctive free photography and visuals.</span></a><a href="https://www.rawpixel.com/" target="_blank" rel="noreferrer"><b>Rawpixel · manual</b><span>Photography, public-domain art and design resources.</span></a><a href="https://undraw.co/illustrations" target="_blank" rel="noreferrer"><b>unDraw · manual</b><span>Free customizable SVG illustrations.</span></a><a href="https://www.svgrepo.com/" target="_blank" rel="noreferrer"><b>SVG Repo · manual</b><span>Large SVG/icon library.</span></a><a href="https://lucide.dev/icons/" target="_blank" rel="noreferrer"><b>Lucide · icons</b><span>Open-source interface icon library.</span></a><a href="https://openmoji.org/" target="_blank" rel="noreferrer"><b>OpenMoji · icons</b><span>Open-source emoji assets in SVG/PNG.</span></a><a href="https://www.reshot.com/" target="_blank" rel="noreferrer"><b>Reshot · manual</b><span>Free icons and illustrations.</span></a><a href="https://picsum.photos/" target="_blank" rel="noreferrer"><b>Lorem Picsum · fallback</b><span>Random placeholder photography for prototypes, not semantic search.</span></a><a href="https://loremflickr.com/" target="_blank" rel="noreferrer"><b>LoremFlickr · fallback</b><span>Keyword-based placeholder photography used only as a low-priority fallback.</span></a><a href="https://www.comfy.org/" target="_blank" rel="noreferrer"><b>ComfyUI · local unlimited</b><span>Run image generation on your own GPU with no cloud image allowance.</span></a><a href="https://aihorde.net/" target="_blank" rel="noreferrer"><b>AI Horde · community</b><span>No-key community generation fallback; queued jobs are kept asynchronous.</span></a></div><h2><?=aih_e(aih_t('assistant',$lang))?></h2><label><?=aih_e(aih_t('system_prompt',$lang))?></label><textarea name="system_prompt" rows="4"><?=aih_e((string)($settings['system_prompt']??''))?></textarea><h2>UI</h2><div class="form-grid"><div><label><?=aih_e(aih_t('default_language',$lang))?></label><select name="ui_language"><?=aih_language_select((string)($settings['ui']['language']??'en'))?></select></div><div><label><?=aih_e(aih_t('default_theme',$lang))?></label><select name="ui_theme"><option value="light" <?=($settings['ui']['theme']??'light')==='light'?'selected':''?>><?=aih_e(aih_t('light',$lang))?></option><option value="dark" <?=($settings['ui']['theme']??'')==='dark'?'selected':''?>><?=aih_e(aih_t('dark',$lang))?></option></select></div></div><h2><?=aih_e(aih_t('security',$lang))?></h2><label class="toggle"><input type="checkbox" name="hcaptcha_enabled" <?=!empty($settings['security']['hcaptcha_enabled'])?'checked':''?>><span><b><?=aih_e(aih_t('hcaptcha_optional',$lang))?></b><small><?=aih_e(aih_t('hcaptcha_follows',$lang))?></small></span></label><div class="form-grid"><div><label>hCaptcha Site Key</label><input name="hcaptcha_sitekey" value="<?=aih_e((string)($settings['security']['hcaptcha_sitekey']??''))?>" placeholder="Optional"></div><div><label>hCaptcha Secret</label><input type="password" name="hcaptcha_secret" placeholder="<?=empty($settings['security']['hcaptcha_secret'])?'Optional secret':'Saved - leave empty to keep'?>"></div></div><label for="currentPassword"><?=aih_e(aih_t('ui_current_login_label',$lang))?></label><input id="currentPassword" type="password" name="current_password" autocomplete="current-password"><label for="newPassword"><?=aih_e(aih_t('ui_change_login_label',$lang))?></label><input id="newPassword" type="password" name="new_password" autocomplete="new-password" minlength="15" maxlength="72" aria-describedby="loginChangeHelp"><label for="confirmPassword"><?=aih_e(aih_t('ui_confirm_login_label',$lang))?></label><input id="confirmPassword" type="password" name="confirm_password" autocomplete="new-password" minlength="15" maxlength="72"><p id="loginChangeHelp" class="muted"><?=aih_e(aih_t('ui_login_change_help',$lang))?></p><section class="integration-card maintenance-card"><div class="integration-head"><div><h2>Cache & refresh</h2><p class="muted">Settings-only maintenance. Clears Smart Search/application cache and resets temporary AI provider cooldown state. It does not delete uploads, generated files, reports, chat history, settings or Figma tokens.</p></div></div><div class="integration-actions"><button class="button ghost" type="button" id="clearCacheBtn">Clear cache & refresh</button><span id="cacheStatus"></span></div></section><div class="save-row"><button class="primary" type="submit"><?=aih_e(aih_t('save_settings',$lang))?></button><span id="settingsStatus"></span></div></form></section><section class="panel"><h2><?=aih_e(aih_t('more_resources',$lang))?></h2><div class="resource-grid"><a href="https://claude.ai/new" target="_blank" rel="noreferrer"><b>Claude Web</b><span>Claude's consumer web app. Useful as a manual free-account fallback; it cannot be auto-routed from this PHP app without a supported API/gateway.</span></a><a href="https://vercel.com/ai-gateway" target="_blank" rel="noreferrer"><b>Vercel AI Gateway</b><span>One OpenAI-compatible key for Claude and many other models. Free accounts currently receive recurring AI Gateway credits.</span></a><a href="https://dash.cloudflare.com/" target="_blank" rel="noreferrer"><b>Cloudflare Workers AI</b><span>Workers Free includes a daily Workers AI allocation and many open models.</span></a><a href="https://build.nvidia.com/" target="_blank" rel="noreferrer"><b>NVIDIA NIM</b><span>Developer-program hosted model APIs for prototyping and development.</span></a><a href="https://copilotstudio.microsoft.com/" target="_blank" rel="noreferrer"><b>Microsoft Copilot Studio</b><span><?=aih_e(aih_t('copilot_note',$lang))?></span></a><a href="https://github.com/features/copilot" target="_blank" rel="noreferrer"><b>GitHub Copilot</b><span>IDE coding assistant. Useful alongside this app, but not a general free inference endpoint for the router.</span></a><a href="https://supabase.com/" target="_blank" rel="noreferrer"><b>Supabase</b><span><?=aih_e(aih_t('supabase_note',$lang))?></span></a><a href="https://huggingface.co/models" target="_blank" rel="noreferrer"><b>Hugging Face Models</b><span>Llama, Gemma, Mistral, DeepSeek, Qwen and many other open models.</span></a></div></section>
